'use strict';
(()=>{
const KEY2='resale-pro-bundles-v2';let lots=[];try{const x=JSON.parse(localStorage.getItem(KEY2)||'[]');if(Array.isArray(x))lots=x}catch{}
const money=n=>'¥'+Math.round(Number(n)||0).toLocaleString('ja-JP');const el=id=>document.getElementById(id);const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const val=id=>Math.max(0,Number(el(id)?.value)||0);const uid=()=>crypto.randomUUID?.()||Date.now()+'-'+Math.random();
const nav=document.querySelector('.tabs');nav.insertAdjacentHTML('beforeend','<button data-tab="bundles">▦<br>セット分析</button>');const section=document.createElement('section');section.id='bundles';section.className='hidden';section.innerHTML=`<h2>セット仕入れ・まとめ売り分析</h2><p class="hint">セット購入価格を各ソフトへ配分し、バラ売りとまとめ売りの利益を比較します。</p>
<div class="card"><h2>セットを登録</h2><input id="lotEdit" type="hidden"><label>セット名 *</label><input id="lotName" placeholder="例：DSソフト10本セット"><div class="twocol"><div><label>セット仕入れ総額（円）</label><input id="lotCost" type="number" min="0" value="3000"></div><div><label>セット販売予定価格（円）</label><input id="lotBundleSale" type="number" min="0" value="5000"></div><div><label>まとめ売り送料（円）</label><input id="lotShip" type="number" min="0" value="750"></div><div><label>まとめ売り手数料（%）</label><input id="lotFee" type="number" min="0" max="100" value="10"></div><div><label>梱包等（円）</label><input id="lotOther" type="number" min="0" value="0"></div><div><label>仕入れ日</label><input id="lotDate" type="date"></div></div><label>セットに含まれるソフト（1行に1本）</label><textarea id="lotLines" rows="7" placeholder="妖怪ウォッチ3 スキヤキ | 3DS | 3500 | 210\n妖怪ウォッチ2 真打 | 3DS | 1800 | 210"></textarea><p class="hint">書式：タイトル | 機種 | バラ売り想定価格 | 送料。1行＝1本。機種・価格・送料は省略可能。仕入れ原価はセット総額を均等配分（端数は最後の1本に加算）。</p><button class="full" id="lotSave">セットを保存して在庫に登録</button><button class="secondary full" id="lotReset" style="margin-top:8px">新しいセットを入力</button></div><div id="lotResults"></div><div class="card"><h2>バックアップについて</h2><p class="hint">セット情報は通常の商品データと一緒にJSONバックアップへ含まれます。復元すると現在のセット・商品情報を置き換えます。</p></div>`;
document.querySelector('main').append(section);
const originalSwitch=window.switchTab;window.switchTab=t=>{originalSwitch(t);if(t==='bundles')draw()};nav.querySelectorAll('button').forEach(b=>b.onclick=()=>window.switchTab(b.dataset.tab));
function persist(){localStorage.setItem(KEY2,JSON.stringify(lots));save();draw()}
function reset(){['lotEdit','lotName','lotLines'].forEach(id=>el(id).value='');el('lotCost').value=3000;el('lotBundleSale').value=5000;el('lotShip').value=750;el('lotFee').value=10;el('lotOther').value=0;el('lotDate').value=new Date().toLocaleDateString('sv-SE')}
function parseLines(){return el('lotLines').value.split('\n').map(line=>line.trim()).filter(Boolean).map(line=>{const a=line.split('|').map(s=>s.trim());return {name:a[0],platform:a[1]||'その他',expected:Math.max(0,Number(a[2])||0),shipping:Math.max(0,Number(a[3]??210)||0)}})}
function createItem(r,lot,index,cost){return {id:uid(),name:r.name,platform:r.platform,condition:'良好',cost:String(cost),expected:String(r.expected),shipping:String(r.shipping),other:'0',fee:'10',buyDate:lot.date,status:'stock',actual:'0',soldDate:'',box:false,manual:false,tested:false,extras:false,notes:'セット仕入れ：'+lot.name,lotId:lot.id,lotIndex:index}}
function updateLinked(lot,rows){const ids=data.filter(x=>x.lotId===lot.id);if(ids.some(x=>x.status==='sold'))throw Error('販売済みの商品を含むセットは編集できません。');data=data.filter(x=>x.lotId!==lot.id);const base=Math.floor(lot.cost/rows.length);rows.forEach((r,i)=>data.push(createItem(r,lot,i,i===rows.length-1?lot.cost-base*(rows.length-1):base)))}
el('lotSave').onclick=()=>{try{const name=el('lotName').value.trim(),rows=parseLines(),cost=val('lotCost'),id=el('lotEdit').value||uid();if(!name||!rows.length)throw Error('セット名とソフトを1本以上入力してください');if(rows.length>200)throw Error('1セット200本以内にしてください');if(rows.some(r=>!r.name))throw Error('タイトルを入力してください');if(val('lotFee')>100)throw Error('手数料は100%以下にしてください');const lot={id,name,cost,bundleSale:val('lotBundleSale'),ship:val('lotShip'),fee:val('lotFee'),other:val('lotOther'),date:el('lotDate').value,rows};updateLinked(lot,rows);const i=lots.findIndex(x=>x.id===id);if(i<0)lots.push(lot);else lots[i]=lot;persist();reset();alert('セットを保存し、各ソフトを在庫に登録しました')}catch(e){alert(e.message)}};
el('lotReset').onclick=reset;
function metrics(lot){const linked=data.filter(x=>x.lotId===lot.id),gross=linked.reduce((s,x)=>s+(x.status==='sold'?Number(x.actual):Number(x.expected)),0),net=linked.reduce((s,x)=>s+profit(x),0),bundle=Math.round(lot.bundleSale*(1-lot.fee/100)-lot.cost-lot.ship-lot.other);return {linked,gross,net,bundle,diff:net-bundle}}
function draw(){el('lotResults').innerHTML=lots.length?lots.slice().reverse().map(lot=>{const m=metrics(lot);return `<div class="card"><div class="row"><b>${safe(lot.name)}</b><span class="pill">${m.linked.length}本</span></div><p class="hint">仕入れ総額 ${money(lot.cost)} · 販売済み ${m.linked.filter(x=>x.status==='sold').length}本</p><div class="twocol"><div><small>バラ売り利益見込み</small><div class="value ${m.net>=0?'green':'red'}">${money(m.net)}</div></div><div><small>まとめ売り利益見込み</small><div class="value ${m.bundle>=0?'green':'red'}">${money(m.bundle)}</div></div></div><p><strong class="${m.diff>=0?'green':'red'}">${m.diff>=0?'バラ売りが':'まとめ売りが'} ${money(Math.abs(m.diff))} 有利</strong></p><p class="hint">バラ売りは登録商品の送料・手数料を使用。販売済み商品の実売価格も反映。セット売りは未販売の全商品を一括で売る仮定です。</p><div class="row"><button class="secondary" data-lotedit="${safe(lot.id)}">編集</button><button class="danger" data-lotdelete="${safe(lot.id)}">削除</button></div></div>`}).join(''):'<div class="empty">セットを登録すると比較結果が表示されます</div>';el('lotResults').querySelectorAll('[data-lotedit]').forEach(b=>b.onclick=()=>edit(b.dataset.lotedit));el('lotResults').querySelectorAll('[data-lotdelete]').forEach(b=>b.onclick=()=>remove(b.dataset.lotdelete))}
function edit(id){const lot=lots.find(x=>x.id===id);if(!lot)return;el('lotEdit').value=id;el('lotName').value=lot.name;el('lotCost').value=lot.cost;el('lotBundleSale').value=lot.bundleSale;el('lotShip').value=lot.ship;el('lotFee').value=lot.fee;el('lotOther').value=lot.other;el('lotDate').value=lot.date;el('lotLines').value=lot.rows.map(r=>[r.name,r.platform,r.expected,r.shipping].join(' | ')).join('\n');window.switchTab('bundles');window.scrollTo(0,0)}
function remove(id){const linked=data.filter(x=>x.lotId===id);if(linked.some(x=>x.status==='sold')){alert('販売済みの商品が含まれるため削除できません');return}if(!confirm('セットと紐づく在庫商品を削除しますか？'))return;data=data.filter(x=>x.lotId!==id);lots=lots.filter(x=>x.id!==id);persist()}
// Export and import both datasets together; preserve compatibility with old v1 backups.
function exportAll(){const blob=new Blob([JSON.stringify({app:'ReSale Pro',version:2,items:data,bundles:lots,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='resale-pro-v2-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
el('export').onclick=exportAll;el('exportTop').onclick=exportAll;
el('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const obj=JSON.parse(await file.text());if(obj.app!=='ReSale Pro'||!Array.isArray(obj.items)|| (obj.bundles!==undefined&&!Array.isArray(obj.bundles)))throw Error('バックアップ形式が違います');if(!confirm('現在の全商品・セットデータをバックアップで置き換えますか？'))return;data=obj.items;lots=obj.bundles||[];persist();alert('復元しました')}catch(err){alert('読み込み失敗: '+err.message)}finally{e.target.value=''}};
reset();draw();
})();
